","data_type":"enum","unit":null,"is_required":false,"enum_values":[{"value":"upper_limit","label_de":"Obergrenze","label_en":"Upper limit","order_index":1,"regulation_reference":"§4.6.2"},{"value":"target_figure","label_de":"Zielwert","label_en":"Target figure","order_index":2,"regulation_reference":"§4.6.2"}],"validation_rules":{"raw":"cost_target_type"},"clause_reference":"§4.6.2","description":"Per §4.6.2: cost target applies as upper limit OR as target figure for planning.","consumer_worksheets":["DIN-276-29"]},{"ws_code":"DIN-276-28","section_code":"C","symbol":"feasibility_checked","label_de":"Machbarkeit geprüft","label_en":"Feasibility checked before target","data_type":"boolean","unit":null,"is_required":false,"enum_values":null,"validation_rules":null,"clause_reference":"§4.6.2","description":"Per §4.6.2: feasibility of the cost target must be checked with regard to the other planning objectives before setting it.","consumer_worksheets":["DIN-276-29"]},{"ws_code":"DIN-276-08","section_code":"C","symbol":"separately_shown_existing_substance","label_de":"Vorhandene Bausubstanz separat ausgewiesen","label_en":"Existing substance shown separately","data_type":"boolean","unit":null,"is_required":false,"enum_values":null,"validation_rules":null,"clause_reference":"§4.2.10","description":"Per §4.2.10: existing-substance value shown separately for the relevant cost groups.","consumer_worksheets":["DIN-276-23","DIN-276-26"]},{"ws_code":"DIN-276-08","section_code":"C","symbol":"separately_shown_contributed_goods","label_de":"Eingebrachte Leistungen separat ausgewiesen","label_en":"Contributed goods shown separately","data_type":"boolean","unit":null,"is_required":false,"enum_values":null,"validation_rules":null,"clause_reference":"§4.2.11","description":"Per §4.2.11: contributed goods/services allocated to relevant cost groups but recognised separately.","consumer_worksheets":["DIN-276-23","DIN-276-26"]},{"ws_code":"DIN-276-08","section_code":"C","symbol":"separately_shown_special_costs","label_de":"Sonderkosten separat ausgewiesen","label_en":"Special costs shown separately","data_type":"boolean","unit":null,"is_required":false,"enum_values":null,"validation_rules":null,"clause_reference":"§4.2.12","description":"Per §4.2.12: special costs from exceptional conditions allocated to relevant cost groups but shown separately.","consumer_worksheets":["DIN-276-23","DIN-276-26"]},{"ws_code":"DIN-276-08","section_code":"C","symbol":"forecasted_costs_assumptions_stated","label_de":"Prognose-Annahmen dokumentiert","label_en":"Forecast assumptions stated","data_type":"boolean","unit":null,"is_required":false,"enum_values":null,"validation_rules":null,"clause_reference":"§4.2.13","description":"Per §4.2.13: assumptions on which the forecast is based must be stated when forecasted costs are present.","consumer_worksheets":["DIN-276-26"]},{"ws_code":"DIN-276-08","section_code":"C","symbol":"separately_shown_forecasted","label_de":"Prognostizierte Kosten separat ausgewiesen","label_en":"Forecasted costs shown separately","data_type":"boolean","unit":null,"is_required":false,"enum_values":null,"validation_rules":null,"clause_reference":"§4.2.13","description":"Per §4.2.13: forecasted costs shown separately at the relevant points in the cost breakdown.","consumer_worksheets":["DIN-276-23","DIN-276-26"]},{"ws_code":"DIN-276-08","section_code":"C","symbol":"separately_shown_risk_costs","label_de":"Risikobehaftete Kosten separat ausgewiesen","label_en":"Risk-related costs shown separately","data_type":"boolean","unit":null,"is_required":false,"enum_values":null,"validation_rules":null,"clause_reference":"§4.2.14","description":"Per §4.2.14: risk-related costs recognised separately at relevant points in the cost breakdown.","consumer_worksheets":["DIN-276-23","DIN-276-26"]},{"ws_code":"DIN-276-02","section_code":"F","symbol":"separate_calculations_per_building","label_de":"Separate Kostenberechnungen pro Gebäude","label_en":"Separate cost calculations per building","data_type":"boolean","unit":null,"is_required":false,"enum_values":null,"validation_rules":null,"clause_reference":"§4.2.8","description":"Per §4.2.8: if multi-building, separate cost calculations must be prepared for each.","consumer_worksheets":["DIN-276-09..29"]}],"equations":[{"ws_code":"DIN-276-23","equation_number":"IDENT-01","formula":"total_construction_costs = kg_100_total + kg_200_total + kg_300_total + kg_400_total + kg_500_total + kg_600_total + kg_700_total + kg_800_total","input_symbols":["kg_100_total","kg_200_total","kg_300_total","kg_400_total","kg_500_total","kg_600_total","kg_700_total","kg_800_total"],"output_symbol":"total_construction_costs","clause_reference":"§3.11","description":"Gesamtkosten = Summe KG 100 bis KG 800"},{"ws_code":"DIN-276-25","equation_number":"IDENT-02","formula":"building_costs = kg_300_total + kg_400_total","input_symbols":["kg_300_total","kg_400_total"],"output_symbol":"building_costs","clause_reference":"§3.12","description":"Bauwerkskosten = KG 300 + KG 400"},{"ws_code":"DIN-276-24","equation_number":"IDENT-03","formula":"cost_parameter = cost / reference_unit","input_symbols":["cost","reference_unit"],"output_symbol":"cost_parameter","clause_reference":"§3.13","description":"Kostenkennwert = Kosten / Bezugseinheit"},{"ws_code":"DIN-276-26","equation_number":"IDENT-04","formula":"deviation_amount = current_stage_total - previous_stage_total","input_symbols":["current_stage_total","previous_stage_total"],"output_symbol":"deviation_amount","clause_reference":"§4.4.2, §4.4.3","description":"Abweichung = aktuelle Kostenermittlung - vorherige Kostenermittlung"}],"compliance":[{"ws_code":"DIN-276-01","code":"REQ-01","title_de":"Scope applicability (§1)","condition":"project_type IN {building,civil_engineering,infrastructure,open_space}","description":"Project type must fall within DIN 276 scope: buildings, civil engineering structures, infrastructure facilities, or open spaces.","clause_reference":"§1"},{"ws_code":"DIN-276-09","code":"REQ-02","title_de":"Cost calculation organised per §5 / Tab.1","condition":"applicable_cost_groups subset_of {100,200,300,400,500,600,700,800}","description":"Per §4.2.2: cost calculations must be organised according to the cost classification in §5 and Tab.1.","clause_reference":"§4.2.2, §5.1, Tab.1"},{"ws_code":"DIN-276-23","code":"REQ-03","title_de":"Total costs recorded completely (§4.2.3)","condition":"total_construction_costs IS NOT NULL","description":"Per §4.2.3: total costs must be recorded and documented in full. Any non-recordable parts must be labelled.","clause_reference":"§4.2.3"},{"ws_code":"DIN-276-01","code":"REQ-04","title_de":"Cost status documented with date (§4.2.4)","condition":"cost_status_date IS NOT NULL","description":"Per §4.2.4: cost status must be documented by specifying the date.","clause_reference":"§4.2.4"},{"ws_code":"DIN-276-01","code":"REQ-05","title_de":"Documents and information basis specified (§4.2.5)","condition":"input_documents_register IS NOT EMPTY","description":"Per §4.2.5: documents and information on which the cost calculation is based must be specified.","clause_reference":"§4.2.5"},{"ws_code":"DIN-276-01","code":"REQ-06","title_de":"Project explanations in cost breakdown (§4.2.6)","condition":"project_scope_description IS NOT EMPTY","description":"Per §4.2.6: explanations of the construction project must be organised in the cost breakdown system.","clause_reference":"§4.2.6"},{"ws_code":"DIN-276-04","code":"REQ-07","title_de":"Cost calculation method specified (§4.2.7)","condition":"cost_calculation_method IS NOT EMPTY AND cost_parameter_library IS NOT EMPTY","description":"Per §4.2.7: cost calculation methods and cost parameter sources used must be stated.","clause_reference":"§4.2.7"},{"ws_code":"DIN-276-01","code":"REQ-08","title_de":"Multi-building: separate calculations (§4.2.8)","condition":"IF multi_building THEN separate_calculations_per_building","description":"Per §4.2.8: if multiple buildings/facilities, separate cost calculations are required for each.","clause_reference":"§4.2.8"},{"ws_code":"DIN-276-01","code":"REQ-09","title_de":"Existing-building project considerations (§4.2.9)","condition":"IF construction_activity == bestand THEN method_documented","description":"Per §4.2.9: detail level / methods / parameters for existing-building projects depend on project-specific circumstances.","clause_reference":"§4.2.9"},{"ws_code":"DIN-276-04","code":"REQ-10","title_de":"Existing substance separately shown (§4.2.10)","condition":"IF existing_substance_value > 0 THEN allocated_and_separated","description":"Per §4.2.10: existing-substance value shown separately for relevant cost groups.","clause_reference":"§4.2.10"},{"ws_code":"DIN-276-04","code":"REQ-11","title_de":"Contributed goods recognised separately (§4.2.11)","condition":"IF contributed_goods_value > 0 THEN allocated_and_separated","description":"Per §4.2.11: values of goods/services provided free of charge allocated to cost groups but recognised separately.","clause_reference":"§4.2.11"},{"ws_code":"DIN-276-04","code":"REQ-12","title_de":"Special costs separately shown (§4.2.12)","condition":"IF special_costs_value > 0 THEN allocated_and_separated","description":"Per §4.2.12: special costs from exceptional conditions allocated to cost groups but shown separately.","clause_reference":"§4.2.12"},{"ws_code":"DIN-276-04","code":"REQ-13","title_de":"Forecasted costs separately shown (§4.2.13)","condition":"IF forecasted_costs_value > 0 THEN assumptions_stated","description":"Per §4.2.13: forecasted costs shown separately, with stated assumptions.","clause_reference":"§4.2.13"},{"ws_code":"DIN-276-04","code":"REQ-14","title_de":"Risk-related costs separately shown (§4.2.14)","condition":"IF risk_costs_value > 0 THEN recognised_separately","description":"Per §4.2.14: risk-related costs recognised separately.","clause_reference":"§4.2.14"},{"ws_code":"DIN-276-01","code":"REQ-15","title_de":"VAT treatment stated (§4.2.15)","condition":"vat_treatment IN {gross,net,mixed}","description":"Per §4.2.15: form of VAT treatment must always be stated.","clause_reference":"§4.2.15"},{"ws_code":"DIN-276-18","code":"REQ-16","title_de":"Cost framework requirements (§4.3.2)","condition":"IF kostenrahmen IN active_stages THEN kostenrahmen_total AT 1st_level","description":"Per §4.3.2: cost framework based on requirements planning; total costs at 1st level of cost breakdown.","clause_reference":"§4.3.2"},{"ws_code":"DIN-276-18","code":"REQ-17","title_de":"Cost estimate requirements (§4.3.3)","condition":"IF kostenschaetzung IN active_stages THEN kostenschaetzung_total AT 2nd_level","description":"Per §4.3.3: cost estimate at 2nd level of cost breakdown.","clause_reference":"§4.3.3"},{"ws_code":"DIN-276-18","code":"REQ-18","title_de":"Cost calculation requirements (§4.3.4)","condition":"IF kostenberechnung IN active_stages THEN kostenberechnung_total AT 3rd_level","description":"Per §4.3.4: cost calculation at 3rd level of cost breakdown.","clause_reference":"§4.3.4"},{"ws_code":"DIN-276-18","code":"REQ-19","title_de":"Cost estimate detail requirements (§4.3.5)","condition":"IF kostenanschlag IN active_stages THEN kostenanschlag_total AT 3rd_level_plus_technical","description":"Per §4.3.5: cost estimate at 3rd level + technical/manufacturing subdivision; organised by award units.","clause_reference":"§4.3.5"},{"ws_code":"DIN-276-18","code":"REQ-20","title_de":"Cost determination requirements (§4.3.7)","condition":"IF kostenfeststellung IN active_stages THEN kostenfeststellung_total AT 3rd_level_or_estimate_structure","description":"Per §4.3.7: cost determination at 3rd level or cost-estimate structure as proof of costs incurred.","clause_reference":"§4.3.7"},{"ws_code":"DIN-276-26","code":"REQ-21","title_de":"Cost control comparison (§4.4)","condition":"stage_to_stage_comparison_documented","description":"Per §4.4.2: current cost determinations continuously compared with previous determinations and cost estimates. (Note: §4.4 is Kostenkontrolle in German; the English translation labels both §4.4 and §4.5 as 'Cost control' — see §4.5 for Kostensteuerung / cost management.)","clause_reference":"§4.4"},{"ws_code":"DIN-276-26","code":"REQ-22","title_de":"Deviations documented (§4.4.3)","condition":"deviations_documented_by_KG_and_type","description":"Per §4.4.3: deviations in individual cost groups must be presented, explained, and documented according to type and scope.","clause_reference":"§4.4.3"},{"ws_code":"DIN-276-26","code":"REQ-23","title_de":"Cost management measures (§4.5)","condition":"cost_control_measures_documented","description":"Per §4.5.2-§4.5.3: deviations assessed; decisions and proposed measures documented. (Note: §4.5 is Kostensteuerung in German — distinct from §4.4 Kostenkontrolle; the English translation renders both as 'Cost control'.)","clause_reference":"§4.5"},{"ws_code":"DIN-276-26","code":"REQ-24","title_de":"Cost specification target defined (§4.6.2)","condition":"cost_target_defined_and_feasibility_checked","description":"Per §4.6.2: cost target defined as upper limit / target figure; feasibility checked before setting.","clause_reference":"§4.6.2"},{"ws_code":"DIN-276-23","code":"REQ-25","title_de":"Building costs aggregation (§3.12)","condition":"building_costs == kg_300_total + kg_400_total","description":"Per §3.12: building costs = sum of KG 300 + KG 400.","clause_reference":"§3.12"},{"ws_code":"DIN-276-23","code":"REQ-26","title_de":"Total cost aggregation (§3.11)","condition":"total_construction_costs == SUM(kg_100..kg_800)","description":"Per §3.11: total costs = sum of KG 100..800.","clause_reference":"§3.11"},{"ws_code":"DIN-276-04","code":"REQ-27","title_de":"Reference units per Tab.2 (1st level)","condition":"reference_units_match_Tab.2","description":"Per §6.2: cost parameters at 1st level use Tab.2 reference units (plot area for KG 100/200; GFA for KG 300/400/600/700/800; outdoor area for KG 500).","clause_reference":"§6.2, Tab.2"},{"ws_code":"DIN-276-04","code":"REQ-28","title_de":"Reference units per Tab.3 (KG 300)","condition":"KG300_reference_units_match_Tab.3","description":"Per §6.3: KG 300 cost parameters use Tab.3 reference units (e.g., excavation volume for KG 310, foundation area for KG 320).","clause_reference":"§6.3, Tab.3"},{"ws_code":"DIN-276-04","code":"REQ-29","title_de":"Reference units per Tab.4 (KG 400)","condition":"KG400_reference_units_match_Tab.4","description":"Per §6.4: KG 400 cost parameters use Tab.4 reference units (e.g., kW for heat output, m³/h for volume flow).","clause_reference":"§6.4, Tab.4"},{"ws_code":"DIN-276-18","code":"REQ-30","title_de":"Execution-oriented breakdown (§5.3)","condition":"IF execution_oriented_breakdown THEN trade_subdivision_documented","description":"Per §5.3: where applicable, costs may be classified primarily by execution (STLB-Bau / VOB Part C trades) with further subdivision.","clause_reference":"§5.3"},{"ws_code":"DIN-276-26","code":"REQ-31","title_de":"Economic efficiency / cost certainty / cost transparency (§4.1)","condition":"objectives_assessed_at_final_approval","description":"Per §4.1: cost planning shall create economic efficiency, cost certainty, and cost transparency.","clause_reference":"§4.1"},{"ws_code":"DIN-276-26","code":"REQ-32","title_de":"Cost planning continuous and systematic (§4.1)","condition":"stages_completed_in_sequence","description":"Per §4.1: cost planning must be carried out continuously and systematically throughout all phases.","clause_reference":"§4.1"}]}$p3c_json$::jsonb;
  v_std uuid;
BEGIN
  -- 1. standard (UPSERT by code)
  INSERT INTO standards (code, title_de, title_en, version)
  SELECT v_data->'standard'->>'code', v_data->'standard'->>'title_de',
         v_data->'standard'->>'title_en', v_data->'standard'->>'version'
  ON CONFLICT (code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, version = excluded.version;
  SELECT id INTO v_std FROM standards WHERE code = v_data->'standard'->>'code';

  -- 2. worksheet templates (UPSERT by standard_id+code)
  INSERT INTO worksheet_templates (standard_id, code, title_de, title_en, phase, archetype, order_index, description)
  SELECT v_std, w->>'code', w->>'title_de', w->>'title_en',
         (w->>'phase')::int, w->>'archetype', (w->>'order_index')::int, w->>'description'
  FROM jsonb_array_elements(v_data->'worksheets') AS w
  ON CONFLICT (standard_id, code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, phase = excluded.phase,
        archetype = excluded.archetype, order_index = excluded.order_index, description = excluded.description;

  -- 3. sections: null fields.section_id, wipe + reinsert (no unique constraint on code), resolve parents
  UPDATE fields SET section_id = NULL
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);
  DELETE FROM worksheet_sections
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);

  INSERT INTO worksheet_sections (worksheet_template_id, code, title_de, order_index)
  SELECT wt.id, s->>'code', s->>'title_de', (s->>'order_index')::int
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code';

  UPDATE worksheet_sections AS child
     SET parent_section_id = parent.id
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code'
  JOIN worksheet_sections parent ON parent.worksheet_template_id = wt.id AND parent.code = s->>'parent_code'
  WHERE s->>'parent_code' IS NOT NULL
    AND child.worksheet_template_id = wt.id
    AND child.code = s->>'code';

  -- 4. fields (UPSERT by worksheet_template_id+symbol; verification_status NOT touched)
  INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit,
                      is_required, enum_values, validation_rules, clause_reference, description, consumer_worksheets)
  SELECT wt.id,
         (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = wt.id AND ws.code = f->>'section_code' LIMIT 1),
         f->>'symbol', f->>'label_de', f->>'label_en', f->>'data_type', f->>'unit',
         (f->>'is_required')::boolean,
         CASE WHEN jsonb_typeof(f->'enum_values') = 'array' THEN f->'enum_values' ELSE NULL END,
         CASE WHEN jsonb_typeof(f->'validation_rules') = 'object' THEN f->'validation_rules' ELSE NULL END,
         f->>'clause_reference', f->>'description',
         CASE WHEN jsonb_typeof(f->'consumer_worksheets') = 'array'
              THEN ARRAY(SELECT jsonb_array_elements_text(f->'consumer_worksheets')) ELSE NULL END
  FROM jsonb_array_elements(v_data->'fields') AS f
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = f->>'ws_code'
  ON CONFLICT (worksheet_template_id, symbol) DO UPDATE
    SET section_id = excluded.section_id, label_de = excluded.label_de, label_en = excluded.label_en,
        data_type = excluded.data_type, unit = excluded.unit, is_required = excluded.is_required,
        enum_values = excluded.enum_values, validation_rules = excluded.validation_rules,
        clause_reference = excluded.clause_reference, description = excluded.description,
        consumer_worksheets = excluded.consumer_worksheets;

  -- 5. equations (UPSERT by worksheet_template_id+equation_number; verification_status preserved)
  INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, clause_reference, description)
  SELECT wt.id, e->>'equation_number', e->>'formula',
         CASE WHEN jsonb_typeof(e->'input_symbols') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(e->'input_symbols')) ELSE NULL END,
         e->>'output_symbol', e->>'clause_reference', e->>'description'
  FROM jsonb_array_elements(v_data->'equations') AS e
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = e->>'ws_code'
  ON CONFLICT (worksheet_template_id, equation_number) DO UPDATE
    SET formula = excluded.formula, input_symbols = excluded.input_symbols, output_symbol = excluded.output_symbol,
        clause_reference = excluded.clause_reference, description = excluded.description;

  -- 6. compliance requirements (UPSERT by worksheet_template_id+code)
  INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, condition, description, clause_reference, severity)
  SELECT wt.id, c->>'code', c->>'title_de', c->>'condition', c->>'description', c->>'clause_reference', 'block'
  FROM jsonb_array_elements(v_data->'compliance') AS c
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = c->>'ws_code'
  ON CONFLICT (worksheet_template_id, code) DO UPDATE
    SET title_de = excluded.title_de, condition = excluded.condition, description = excluded.description,
        clause_reference = excluded.clause_reference, severity = excluded.severity;
END
$p3c_do$;
